mapper.select:
select count(distinct registration.member_id) as verifiedHeads,
       coalesce(sum(registration.payable_amount), 0) as verifiedSales
from coop_group_member_verify member_verify
inner join cms_registration registration on registration.id = member_verify.registration_id
where member_verify.topic_id = #{topicId}
  and registration.owner_type = 1
  and registration.owner_id = #{topicId}
  and registration.payment_status = 2
  and registration.verification_status = 1
  and exists (
      select 1
      from coop_group_verify group_verify
      where group_verify.topic_id = #{topicId}
        and group_verify.activity_id = member_verify.activity_id
        and group_verify.merchant_member_id = #{merchantMemberId}
  )

select count(distinct registration.member_id) as verifiedHeads,
       coalesce(sum(registration.payable_amount), 0) as verifiedSales
from coop_group_member_verify member_verify
inner join cms_registration registration on registration.id = member_verify.registration_id
where member_verify.topic_id = #{topicId}
  and ((registration.owner_type = 1 and registration.owner_id = #{topicId})
      or (registration.owner_type = 2 and exists (
          select 1 from cms_activity activity
          where activity.id = registration.owner_id
            and activity.topic_id = #{topicId}
            and activity.del_flag = 0
      )))
  and registration.payment_status = 2
  and registration.verification_status = 1
  and exists (
      select 1 from coop_group_verify group_verify
      where group_verify.topic_id = #{topicId}
        and group_verify.activity_id = member_verify.activity_id
        and group_verify.merchant_member_id = #{merchantMemberId}
  )

select id, topic_id, activity_id, coop_order_id, merchant_member_id, leader_member_id, verify_time
from coop_group_verify
where topic_id = #{topicId}

select gv.id as id, gv.topic_id as topicId, t.name as topicName, gv.coop_order_id as coopOrderId, gv.merchant_member_id as merchantMemberId, mm.nickname as merchantName, gv.leader_member_id as leaderMemberId, lm.nickname as leaderName, gv.verify_time as verifyTime from coop_group_verify gv left join cms_topic t on t.id = gv.topic_id left join ums_member mm on mm.id = gv.merchant_member_id left join ums_member lm on lm.id = gv.leader_member_id
and gv.topic_id = #{topicId} and gv.merchant_member_id = #{merchantMemberId} and gv.leader_member_id = #{leaderMemberId}
order by gv.verify_time desc
